"""
Regression tests verifying ModelService backward compatibility with retrained artifacts (R1, R5).
"""
from pathlib import Path
import pytest

from car_price_predictor.services.model_service import ModelService
from car_price_predictor.training.pipeline import TrainingConfig, TrainingPipeline


class TestRetrainedModelCompatibility:
    """Verifies that artifacts generated by the training pipeline integrate with ModelService seamlessly."""

    @pytest.fixture(scope="class")
    @classmethod
    def retrained_artifact(cls, tmp_path_factory):
        """Trains a fast synthetic candidate model and returns the artifact path."""
        tmp_dir = tmp_path_factory.mktemp("retrain_compat")
        config = TrainingConfig(
            use_sample=True,
            n_samples=100,
            n_estimators=10,
            random_state=42,
            output_dir=tmp_dir,
            version="v-compat-test",
            enforce_gates=False,
        )
        pipeline = TrainingPipeline(config)
        result = pipeline.run()
        assert result["status"] == "success"
        assert result["joblib_path"] is not None
        return Path(result["joblib_path"])

    def test_retrained_artifact_loads_into_model_service(self, retrained_artifact):
        """ModelService successfully loads the newly serialized model artifact."""
        service = ModelService(model_path=retrained_artifact, load_on_init=True)
        assert service.is_ready()
        assert len(service.brand_map) > 0
        assert len(service.model_map) > 0
        assert len(service.feature_columns) == 14

    def test_retrained_artifact_inference_contract(self, retrained_artifact, valid_payload):
        """ModelService performs prediction on retrained model returning positive float."""
        service = ModelService(model_path=retrained_artifact, load_on_init=True)
        input_df = service.preprocessor.preprocess(valid_payload)

        point_pred = service.predict(input_df)
        assert isinstance(point_pred, float)
        assert point_pred > 0.0

    def test_retrained_artifact_predict_with_interval(self, retrained_artifact, valid_payload):
        """Retrained model generates valid empirical confidence intervals."""
        service = ModelService(model_path=retrained_artifact, load_on_init=True)
        input_df = service.preprocessor.preprocess(valid_payload)

        pred, lower, upper = service.predict_with_interval(input_df, confidence_level=0.80)
        assert lower <= pred <= upper
        assert lower >= 0.0

    def test_retrained_artifact_hierarchy_accessors(self, retrained_artifact):
        """Retrained artifact exposes brand and model hierarchy accessors correctly."""
        service = ModelService(model_path=retrained_artifact, load_on_init=True)
        brands = service.get_brands()
        hierarchy = service.get_hierarchy()

        assert len(brands) > 0
        assert isinstance(hierarchy, dict)
        first_brand = brands[0]
        models = service.get_models_for_brand(first_brand)
        assert isinstance(models, list)

    def test_baseline_golden_benchmarks_remain_unaffected(self, client, golden_benchmarks):
        """Verifies that the canonical root car_price_model.joblib continues to produce exact golden prices."""
        for record in golden_benchmarks:
            res = client.post("/api/v1/predict", json=record["req"])
            assert res.status_code == 200
            assert res.get_json()["price"] == record["formatted_price"]
